-- Apply in Supabase SQL editor or with supabase db push. Never expose service_role.
create extension if not exists pgcrypto;
create type public.workspace_role as enum ('OWNER','ADMIN','MEMBER');
create table public.profiles(id uuid primary key references auth.users on delete cascade, full_name text not null default '', username text unique check(username ~ '^[a-z0-9_]{3,32}$'), created_at timestamptz not null default now());
create table public.workspaces(id uuid primary key default gen_random_uuid(), name text not null, deleted_at timestamptz, created_at timestamptz not null default now());
create table public.workspace_members(workspace_id uuid references public.workspaces on delete cascade,user_id uuid references auth.users on delete cascade,role public.workspace_role not null default 'MEMBER',created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table public.business_profiles(workspace_id uuid primary key references public.workspaces on delete cascade,data jsonb not null default '{}',version bigint not null default 0,updated_at timestamptz not null default now());
create table public.subscriptions(workspace_id uuid primary key references public.workspaces on delete cascade,provider_customer_id text unique,provider_subscription_id text unique,plan text,status text not null default 'incomplete',billing_interval text,current_period_end timestamptz,updated_at timestamptz not null default now());
create table public.integration_connections(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces on delete cascade,provider text not null check(provider in ('google_business','gmail','instagram')),connected_user uuid references auth.users,provider_account_id text,display_name text,status text not null default 'disconnected',encrypted_credentials text,scopes text[] not null default '{}',expires_at timestamptz,last_synced_at timestamptz,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,provider));
create table public.notification_preferences(workspace_id uuid references public.workspaces on delete cascade,user_id uuid references auth.users on delete cascade,event_type text not null,channel text not null check(channel in ('IN_APP','EMAIL','SMS')),enabled boolean not null default false,primary key(workspace_id,user_id,event_type,channel),foreign key(workspace_id,user_id) references public.workspace_members(workspace_id,user_id) on delete cascade);
create table public.notification_recipients(workspace_id uuid references public.workspaces on delete cascade,user_id uuid references auth.users on delete cascade,event_type text not null,primary key(workspace_id,user_id,event_type),foreign key(workspace_id,user_id) references public.workspace_members(workspace_id,user_id) on delete cascade);
create table public.notifications(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces on delete cascade,recipient_id uuid not null references auth.users on delete cascade,event_type text not null,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now(),related_entity_type text,related_entity_id text);
create table public.audit_logs(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces,actor_id uuid,event text not null,created_at timestamptz not null default now());
create table public.workspace_invites(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces on delete cascade,email text not null,role public.workspace_role not null check(role<>'OWNER'),token_hash text unique not null,status text not null default 'pending',expires_at timestamptz not null,created_at timestamptz not null default now());
create table public.oauth_states(token_hash text primary key,workspace_id uuid not null references public.workspaces on delete cascade,user_id uuid not null references auth.users,provider text not null,verifier text not null,expires_at timestamptz not null);
create table public.billing_events(id text primary key,created_at timestamptz not null default now());
create table public.rate_limits(key text primary key,count integer not null,started_at timestamptz not null);
create function public.member_role(w uuid) returns public.workspace_role language sql stable security definer set search_path='' as $$select m.role from public.workspace_members m join public.workspaces w on w.id=m.workspace_id where m.workspace_id=$1 and m.user_id=auth.uid() and w.deleted_at is null$$;
create function public.provision_user() returns trigger language plpgsql security definer set search_path='' as $$declare w uuid;begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));insert into public.workspaces(name) values(coalesce(nullif(new.raw_user_meta_data->>'business_name',''),'Mijn bedrijf')) returning id into w;insert into public.workspace_members(workspace_id,user_id,role) values(w,new.id,'OWNER');insert into public.business_profiles(workspace_id) values(w);return new;end$$;
create trigger provision_mavix_user after insert on auth.users for each row execute function public.provision_user();
create function public.consume_rate_limit(p_key text,p_limit integer,p_window integer) returns boolean language plpgsql security definer set search_path='' as $$declare n integer;begin insert into public.rate_limits(key,count,started_at) values(p_key,1,now()) on conflict(key) do update set count=case when public.rate_limits.started_at<now()-make_interval(secs=>p_window) then 1 else public.rate_limits.count+1 end,started_at=case when public.rate_limits.started_at<now()-make_interval(secs=>p_window) then now() else public.rate_limits.started_at end returning count into n;return n<=p_limit;end$$;
revoke all on function public.consume_rate_limit(text,integer,integer) from public,anon,authenticated;
grant execute on function public.consume_rate_limit(text,integer,integer) to service_role;
do $$declare t text;begin foreach t in array array['profiles','workspaces','workspace_members','business_profiles','subscriptions','integration_connections','notification_preferences','notification_recipients','notifications','audit_logs','workspace_invites','oauth_states','billing_events','rate_limits'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid());
create policy workspace_read on public.workspaces for select to authenticated using(public.member_role(id) is not null);
create policy members_read on public.workspace_members for select to authenticated using(public.member_role(workspace_id) is not null);
create policy business_read on public.business_profiles for select to authenticated using(public.member_role(workspace_id) is not null);
create policy business_write on public.business_profiles for update to authenticated using(public.member_role(workspace_id) in ('OWNER','ADMIN')) with check(public.member_role(workspace_id) in ('OWNER','ADMIN'));
create policy subscription_read on public.subscriptions for select to authenticated using(public.member_role(workspace_id)='OWNER');
create policy preferences_read on public.notification_preferences for select to authenticated using(public.member_role(workspace_id) is not null and user_id=auth.uid());
create policy preferences_write on public.notification_preferences for all to authenticated using(public.member_role(workspace_id) is not null and user_id=auth.uid()) with check(public.member_role(workspace_id) is not null and user_id=auth.uid());
create policy notification_read on public.notifications for select to authenticated using(recipient_id=auth.uid() and public.member_role(workspace_id) is not null);
create policy notification_update on public.notifications for update to authenticated using(recipient_id=auth.uid() and public.member_role(workspace_id) is not null) with check(recipient_id=auth.uid() and public.member_role(workspace_id) is not null);
-- Secret-bearing tables intentionally have no browser-access policies.
revoke all on public.integration_connections,public.oauth_states,public.workspace_invites,public.rate_limits,public.billing_events from anon,authenticated;
revoke all on function public.provision_user() from public,anon,authenticated;
create function public.accept_invitation(p_hash text,p_user uuid,p_email text) returns void language plpgsql security definer set search_path='' as $$declare i public.workspace_invites;begin select * into i from public.workspace_invites where token_hash=p_hash and status='pending' and expires_at>now() and email=p_email for update;if i.id is null then raise exception 'invalid invitation';end if;insert into public.workspace_members(workspace_id,user_id,role) values(i.workspace_id,p_user,i.role) on conflict do nothing;update public.workspace_invites set status='accepted' where id=i.id;insert into public.audit_logs(workspace_id,actor_id,event) values(i.workspace_id,p_user,'member_joined');end$$;
revoke all on function public.accept_invitation(text,uuid,text) from public,anon,authenticated;
grant execute on function public.accept_invitation(text,uuid,text) to service_role;
-- Only read_at is writable by the recipient, never notification contents/recipient.
revoke update on public.notifications from authenticated;
grant update(read_at) on public.notifications to authenticated;
